const CACHE = "goalak-v151";
/* top-clubs.js is a static DATA file (last season's top five per league + the ESPN competition-id
   map). It is cache-first like every other asset here, so it refreshes on the next CACHE bump —
   which is the right cadence: the club list only changes once a season. */
const SHELL = ["./", "index.html", "club-facts.json", "manifest.json", "icon-192.png", "icon-512.png", "icon-180.png", "favicon.svg", "logo-head.svg", "logo-mark-pos.svg", "logo-mark-rev.svg", "badge.png", "top-clubs.js"];
/* Third-party hosts are never intercepted (live data + shared state must ride the network). */
const BYPASS = /espn\.com|espncdn\.com|googleapis\.com|gstatic\.com|flagcdn\.com|textdb\.online|workers\.dev/;

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).catch(() => {}));
  self.skipWaiting();
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys()
      /* gk-killed-cards is not a build cache: it holds the short-lived tombstones that
         stop an out-of-order push re-pinning a match that has already finished. Sweeping
         it on every deploy threw those away and let a stale card come back. */
      .then(ks => Promise.all(ks.filter(k => k !== CACHE && k !== "gk-killed-cards").map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

function isShellReq(req) {
  if (req.mode === "navigate") return true;
  const scopePath = new URL(self.registration.scope).pathname;
  const p = new URL(req.url).pathname;
  return p === scopePath || p === scopePath + "index.html";
}

/* Responses that arrived via redirect cannot be replayed for navigations; re-wrap the body. */
async function unredirect(r) {
  if (!r.redirected) return r;
  const b = await r.blob();
  return new Response(b, { status: 200, headers: { "Content-Type": r.headers.get("Content-Type") || "text/html" } });
}

/* ===== Web Push ===== payload (JSON) from the goalak-push Worker:
   { title, body, icon?, badge?, tag, renotify?, silent?, url } */
self.addEventListener("push", e => {
  let d = {};
  try { d = e.data ? e.data.json() : {}; }
  catch (_) { try { d = { title: "Goallak", body: e.data.text() }; } catch (__) { d = {}; } }
  const opts = {
    body: d.body || "",
    icon: d.icon || "./icon-192.png",
    badge: d.badge || "./badge.png",
    tag: d.tag || undefined,
    renotify: d.renotify != null ? !!d.renotify : !!d.tag,
    silent: !!d.silent,
    /* a LIVE match card stays in the shade and updates itself in place: same tag, no
       re-alert, no buzz. requireInteraction keeps Android from auto-dismissing it. */
    requireInteraction: !!d.sticky,
    timestamp: d.ts || Date.now(),
    data: { url: d.url || "./" },
    vibrate: d.silent ? undefined : [80, 40, 80]
  };
  e.waitUntil((async () => {
    /* FULL TIME CLOSES THE LIVE CARD. A pinned card carries requireInteraction, so Android
       keeps it in the shade until somebody swipes it - without this every match a user
       follows left a frozen 90th-minute score behind for ever. */
    try {
      const shown = await self.registration.getNotifications();
      if (d.close) {
        for (const n of shown) if (n.tag === d.close) n.close();
        /* remember the kill: push delivery is not ordered, and a live-card update queued a
           tick before full time can arrive AFTER the closing push - re-pinning a frozen
           90th-minute card for hours. The tombstone outlives the worker via the cache API. */
        try {
          const kc = await caches.open("gk-killed-cards");
          await kc.put("/" + encodeURIComponent(d.close), new Response(String(Date.now())));
        } catch (_) {}
      }
      /* and a belt-and-braces sweep: any card older than three hours belongs to a match that
         finished while the phone was off, whose closing push has long since expired */
      const cut = Date.now() - 3 * 3600000;
      for (const n of shown) {
        /* `|| 0` closed EVERY card on any engine that does not implement Notification.timestamp:
           zero is older than any cut-off, so the next goal alert destroyed the live card. An
           unknown age is not an old age. */
        if (n.tag && n.tag.indexOf("card-") === 0 && n.timestamp && n.timestamp < cut) n.close();
      }
    } catch (_) { /* getNotifications is not everywhere; the card is still replaced by tag */ }
    /* a push event must show SOMETHING or the browser shows its own generic notice - so a
       resurrected card is shown silently and closed in the same breath: no buzz, no shade entry */
    let resurrected = false;
    if (opts.tag && opts.tag.indexOf("card-") === 0) {
      try {
        const kc = await caches.open("gk-killed-cards");
        const hit = await kc.match("/" + encodeURIComponent(opts.tag));
        if (hit) {
          const t = Number(await hit.text()) || 0;
          if (Date.now() - t < 15 * 60000) resurrected = true;
          else await kc.delete("/" + encodeURIComponent(opts.tag));
        }
      } catch (_) {}
    }
    await self.registration.showNotification(d.title || "Goallak", opts);
    if (resurrected) {
      try {
        const ns = await self.registration.getNotifications({ tag: opts.tag });
        for (const n of ns) n.close();
      } catch (_) {}
    }
  })());
});

/* THE ENDPOINT CAN BE ROTATED OUT FROM UNDER US. When a push service reissues a subscription
   there is no user-visible event: the old endpoint starts returning 410, the worker prunes it,
   and the person is silently unsubscribed with the switch in Settings still reading ON. This
   re-subscribes with the same key and tells the page to save the new record. */
self.addEventListener("pushsubscriptionchange", e => {
  e.waitUntil((async () => {
    try {
      const old = e.oldSubscription || await self.registration.pushManager.getSubscription();
      const key = (e.newSubscription && e.newSubscription.options && e.newSubscription.options.applicationServerKey)
               || (old && old.options && old.options.applicationServerKey);
      if (!key) return;
      const sub = e.newSubscription || await self.registration.pushManager.subscribe({
        userVisibleOnly: true, applicationServerKey: key
      });
      const wins = await clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const c of wins) c.postMessage({ gk: "pushsub", sub: sub.toJSON(), old: old ? old.endpoint : null });
    } catch (_) { /* nothing more the worker can do alone; the page re-saves on next open */ }
  })());
});
self.addEventListener("notificationclick", e => {
  e.notification.close();
  const target = (e.notification.data && e.notification.data.url) || "./";
  e.waitUntil((async () => {
    const wins = await clients.matchAll({ type: "window", includeUncontrolled: true });
    for (const c of wins) {
      if ("focus" in c) { try { await c.focus(); if ("navigate" in c) { try { await c.navigate(target); } catch (_) {} } return; } catch (_) {} }
    }
    if (clients.openWindow) { try { return await clients.openWindow(target); } catch (_) {} }
  })());
});

self.addEventListener("fetch", e => {
  const url = e.request.url;
  if (e.request.method !== "GET" || BYPASS.test(url)) return;
  /* never let the worker mediate its own script — the update path must always hit the network */
  if (new URL(url).pathname.endsWith("sw.js")) return;
  if (isShellReq(e.request)) {
    /* EVERY navigation is network-first with no-store, so a deploy shows on the next open.
       THE KEY IS PER PAGE. It used to write every navigation into the single "index.html"
       entry, and isShellReq is true for ALL navigations - so opening /fantasy/ overwrote the
       cached main app with the fantasy page, and the next offline open of / served Fantasy.
       Two pages, two keys; only the app root still owns "index.html". */
    const path = new URL(url).pathname;
    const scope = new URL(self.registration.scope).pathname;
    const isRoot = path === scope || path === scope + "index.html";
    const key = isRoot ? "index.html" : path;
    e.respondWith((async () => {
      try {
        let r = await fetch(url, { cache: "no-store" });
        if (!r.ok) throw new Error("http " + r.status);
        r = await unredirect(r);
        const cp = r.clone();
        e.waitUntil(caches.open(CACHE).then(c => c.put(key, cp)).catch(() => {}));
        return r;
      } catch (_) {
        /* offline: its own cached copy first. The app shell used to be the last resort for
           EVERY navigation, so a first-ever offline open of /fantasy/ served the main app's
           HTML at the /fantasy/ URL, where its relative sw.js, top-clubs.js and manifest all
           resolve to the wrong files. Only the root falls back to the root. */
        const m = await caches.match(key);
        if (m) return m;
        return isRoot ? ((await caches.match("index.html")) || caches.match("./"))
                      : new Response("<!doctype html><meta charset=utf-8><title>Goallak</title>"
                                     + "<meta name=viewport content=\"width=device-width,initial-scale=1\">"
                                     /* the app is Arabic-first and supports a light theme; the fallback
                                        page had no language, no direction and a hardcoded dark ground */
                                     + "<body dir=rtl lang=ar style=\"font:16px system-ui;padding:24px;"
                                     + "background:#0a1230;color:#fff\">"
                                     + "<p>مفيش نت — افتح تاني لما يرجع</p>"
                                     + "<p dir=ltr lang=en style=opacity:.75>You are offline. Reopen when you are back.</p>"
                                     + "</body>",
                                     { headers: { "Content-Type": "text/html; charset=utf-8" } });
      }
    })());
    return;
  }
  /* THE GAME'S DATA IS NOT A STATIC ASSET. clubs.json, prices.json, calendar.json and
     crests.json took the cache-first path, so a returning player ran today's fantasy code
     against the PREVIOUS deploy's rosters and round windows - and shipping a corrected
     calendar reached nobody until the cache name happened to change. They revalidate now:
     the cached copy answers instantly and is replaced in the background. */
  if (/\/fantasy\/[a-z-]+\.json(\?|$)/.test(url)) {
    e.respondWith((async () => {
      const c = await caches.open(CACHE);
      const m = await c.match(e.request);
      const net = fetch(e.request, { cache: "no-store" })
        .then(r => { if (r && r.ok && !r.redirected) c.put(e.request, r.clone()); return r; })
        .catch(() => null);
      if (m) { e.waitUntil(net); return m; }
      return (await net) || Response.error();
    })());
    return;
  }
  /* static assets: cache-first */
  e.respondWith((async () => {
    const m = await caches.match(e.request);
    if (m) return m;
    const r = await fetch(e.request);
    if (r && r.ok && !r.redirected) {
      const cp = r.clone();
      e.waitUntil(caches.open(CACHE).then(c => c.put(e.request, cp)).catch(() => {}));
    }
    return r;
  })());
});
